import{_ as t,a0 as l,w as o,s as r,ao as c,I as p,x as e,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"使用 qrcp 在你的手機和 Linux 之間傳輸文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 qrcp 在你的手機和 Linux 之間傳輸文件 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 qrcp 在你的手機和 Linux 之間傳輸文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 qrcp 在你的手機和 Linux 之間傳輸文件 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211110 Transfer files between your phone and Linux with this open source tool","title":"使用 qrcp 在你的手機和 Linux 之間傳輸文件","tag":"202111","desc":""},"relativePath":"202111/20211110 Transfer files between your phone and Linux with this open source tool.md","filePath":"[post].md"}'),d={name:"202111/20211110 Transfer files between your phone and Linux with this open source tool.md"};function u(h,s,g,f,k,m){const a=l("Link");return o(),r("div",null,[s[15]||(s[15]=c(`<h1 id="使用-qrcp-在你的手機和-linux-之間傳輸文件" tabindex="-1">使用 qrcp 在你的手機和 Linux 之間傳輸文件 <a class="header-anchor" href="#使用-qrcp-在你的手機和-linux-之間傳輸文件" aria-label="Permalink to “使用 qrcp 在你的手機和 Linux 之間傳輸文件”">​</a></h1><blockquote><p>qrcp 項目提供了一種快速地從你的 iPhone 或 Android 設備中複製文件到你的 Linux 電腦的方法，反之也可。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202111/19/114121wt40ilipix1oo1zh.jpg" alt=""></p><p>你是否在尋找一種快速複製文件的方法，從你的 iPhone 或 Android 移動設備到你的 Linux 電腦，或者從你的 Linux 電腦到你的設備？我最近發現了一個開源的應用，它很容易安裝，並且傳輸文件只需一個二維碼。</p><p><code>qrcp</code> 項目提供了一個命令，可以在你的終端生成一個二維碼，讓你通過網絡向你的電腦發送或接收文件。</p><h3 id="在-linux、windows-或-mac-上安裝-qrcp" tabindex="-1">在 Linux、Windows 或 Mac 上安裝 qrcp <a class="header-anchor" href="#在-linux、windows-或-mac-上安裝-qrcp" aria-label="Permalink to “在 Linux、Windows 或 Mac 上安裝 qrcp”">​</a></h3><p>開發者 Claudio d&#39;Angelis 以 MIT 許可證發佈了 <code>qrcp</code> 應用。我發現它很容易安裝，也很容易使用。它適用於 Linux、Windows 和 macOS，可以作為 RPM、DEB 或 tarball 下載。它為幾乎所有的平台做了構建，包括樹莓派。</p><p>如果你想在 Linux 上安裝它，下載 RPM 或 DEB，並使用你的包管理器進行本地安裝。例如，在 Fedora、CentOS 或 Mageia，或類似的平台上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install ./qrcp*rpm</span></span></code></pre></div><p>如果你只是想試試，你可以下載 tar.gz 壓縮包並在本地運行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar --extract --file qrcp*tar.gz</span></span>
<span class="line"><span>$ ./qrcp version</span></span>
<span class="line"><span>qrcp 0.x.y</span></span></code></pre></div><h3 id="設置-qrcp" tabindex="-1">設置 qrcp <a class="header-anchor" href="#設置-qrcp" aria-label="Permalink to “設置 qrcp”">​</a></h3><p>你可以通過使用 <code>--help</code> 選項查看所有可用的 <code>qrcp</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ qrcp --help</span></span>
<span class="line"><span>$ ./qrcp --help</span></span>
<span class="line"><span>Usage:</span></span>
<span class="line"><span> qrcp [flags]</span></span>
<span class="line"><span> qrcp [command]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Available Commands:</span></span>
<span class="line"><span> completion  Generate completion script</span></span>
<span class="line"><span> config      Configure qrcp</span></span>
<span class="line"><span> help        Help about any command</span></span>
<span class="line"><span> receive     Receive one or more files</span></span>
<span class="line"><span> send        Send a file(s) or directories from this host</span></span>
<span class="line"><span> version     Print version number and build information.</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>默認配置文件位於 <code>~/.config/qrcp/config.json</code> ，你可以使用你喜歡的編輯器編輯，或從命令列調用配置嚮導來配置應用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ qrcp config</span></span></code></pre></div><p>第一步是創建一個配置文件。<code>qrcp config</code> 命令將帶你完成這個過程，但會問你幾個問題。</p><p>第一個問題是要求你提供一個“完全限定域名”。如果你在一個不使用完全限定域名的本地網絡上使用 <code>qrcp</code>（或者你不知道哪種方式），那麼就把這個留空。<code>qrcp</code> 命令將使用你的本地 IP 地址代替。</p><p>下一個問題是提示你選擇端口。大多數防火牆會阻止非標準的端口，但會將 8080 端口作為互聯網流量的情況並不少見。如果你的防火牆屏蔽了 8080 端口，那麼你還是要添加一個例外。假設你的系統使用 <code>firewalld</code>，你可以用這個命令允許 8080 端口的流量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --add-port 8080/tcp --permanent</span></span></code></pre></div><p>拒絕在“傳輸完成後保持網絡連接”的選項，讓 <code>qrcp</code> 生成一個隨機路徑。</p><p>假設你在一個可信的網絡上，使用 HTTP（而不是 HTTPS）連接，那麼你不必配置 TLS。</p><p>配置保存在 <code>~/.config/qrcp/config.json</code> 中，並且之後可以編輯，所以如果你想改變設置，它很容易更新。</p><p>更新後的配置看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;fqdn&quot;: &quot;&quot;,</span></span>
<span class="line"><span>  &quot;interface&quot;: &quot;wlp0s20f3&quot;,</span></span>
<span class="line"><span>  &quot;port&quot;: 8080,</span></span>
<span class="line"><span>  &quot;keepAlive&quot;: false,</span></span>
<span class="line"><span>  &quot;path&quot;: &quot;&quot;,</span></span>
<span class="line"><span>  &quot;secure&quot;: false,</span></span>
<span class="line"><span>  &quot;tls-key&quot;: &quot;&quot;,</span></span>
<span class="line"><span>  &quot;tls-cert&quot;: &quot;&quot;,</span></span>
<span class="line"><span>  &quot;output&quot;: &quot;/home/don&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="用-qrcp-傳輸文件" tabindex="-1">用 qrcp 傳輸文件 <a class="header-anchor" href="#用-qrcp-傳輸文件" aria-label="Permalink to “用 qrcp 傳輸文件”">​</a></h3><p>現在你已經準備好從你的 Linux 電腦向你的移動設備發送一個文件。在這個例子中，我使用了我的 iPhone，它完全不支持 Linux，這是臭名昭著的。這個過程在安卓設備上是完全一樣的。</p><p>我是這樣做的。首先，我在我的電腦上創建一個示例文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Hello world&quot;&gt; ~/example.txt</span></span></code></pre></div><p>接下來，我使用 <code>send</code> 子命令將文件從我的 Linux 電腦發送到我的手機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linux~$ qrcp send example.txt</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/send-example.png" alt="example of sending a file"></p><p><em>使用 <code>qrcp send example.txt</code> 發送文件的例子（CC BY-SA 4.0）</em></p><p>我打開我的相機應用（在 Android 上，我使用一個保護隱私的專用二維碼掃描器），iPhone 掃描二維碼並在我的手機上啓動 Safari 瀏覽器。最後，我點擊“下載”按鈕。</p><p><img src="https://opensource.com/sites/default/files/download-example.png" alt="example download"></p><p><em>下載示例 .txt 文件（CC BY-SA 4.0）</em></p><h3 id="用-qrcp-接收文件" tabindex="-1">用 qrcp 接收文件 <a class="header-anchor" href="#用-qrcp-接收文件" aria-label="Permalink to “用 qrcp 接收文件”">​</a></h3><p>接收文件也一樣簡單，只是命令略有不同：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ qrcp receive</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/receive-file.png" alt="example of receiving a file"></p><p><em>使用 <code>qrcp receive</code> 命令接收一個文件（CC BY-SA 4.0）</em></p><p>我掃描了二維碼，它再次啓動了我手機上的 Safari 瀏覽器，但這次出現了一些不同，因為我正在將文件從我的 iPhone 發送到 Linux 電腦上。</p><p><img src="https://opensource.com/sites/default/files/select-file.jpg" alt="example of selecting a file"></p><p><em>選擇一個要傳輸的文件（CC BY-SA 4.0）</em></p><p>我點擊“選擇文件”，它讓我選擇想發送的文件。</p><p><img src="https://opensource.com/sites/default/files/default-location.png" alt="file appears in default location"></p><p><em>文件被下載到默認位置（CC BY-SA 4.0）</em></p><p>發送文件後，是在我的配置中指定的默認位置找到了文件。</p><h3 id="嘗試-qrcp" tabindex="-1">嘗試 qrcp <a class="header-anchor" href="#嘗試-qrcp" aria-label="Permalink to “嘗試 qrcp”">​</a></h3><p>項目文檔很簡短但已足夠，除了最初提出這個想法的 Claudio d&#39;Angelis 之外，它還有開發者社區的支持。社區歡迎你加入他們，該應用將改變你對移動設備之間文件傳輸的看法。試試吧！</p><hr>`,51)),p("p",null,[s[1]||(s[1]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/21/11/transfer-files-phone-linux"},{default:i(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/21/11/transfer-files-phone-linux",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/don-watkins"},{default:i(()=>[...s[2]||(s[2]=[e("Don Watkins",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const C=t(d,[["render",u]]);export{x as __pageData,C as default};
